class Solution {
public:
    int minSizeSubarray(vector<int>& nums, int target) {
        long long total = 0;
        for (int x : nums) total += x;
        int n = nums.size();
        long long full = target / total;
        int rem = target % total;
        if (rem == 0) return full * n;
        vector<int> arr = nums;
        arr.insert(arr.end(), nums.begin(), nums.end());
        long long curr = 0;
        int left = 0, min_len = 1e9;
        for (int right = 0; right < arr.size(); right++) {
            curr += arr[right];
            while (curr > rem && left <= right) {
                curr -= arr[left++];
            }
            if (curr == rem) min_len = min(min_len, right - left + 1);
        }
        if (min_len == 1e9) return -1;
        return full * n + min_len;
    }
};

class Solution {
    public int minSizeSubarray(int[] nums, int target) {
        long total = 0;
        for (int x : nums) total += x;
        int n = nums.length;
        long full = target / total;
        int rem = (int) (target % total);
        if (rem == 0) return (int) (full * n);
        int[] arr = new int[2 * n];
        System.arraycopy(nums, 0, arr, 0, n);
        System.arraycopy(nums, 0, arr, n, n);
        long curr = 0;
        int left = 0, minLen = Integer.MAX_VALUE;
        for (int right = 0; right < arr.length; right++) {
            curr += arr[right];
            while (curr > rem && left <= right) {
                curr -= arr[left++];
            }
            if (curr == rem) minLen = Math.min(minLen, right - left + 1);
        }
        if (minLen == Integer.MAX_VALUE) return -1;
        return (int) (full * n + minLen);
    }
}

