var minSizeSubarray = function(nums, target) {
    let total = 0;
    for (const x of nums) total += x;
    const n = nums.length;
    const full = Math.floor(target / total);
    const rem = target % total;
    if (rem === 0) return full * n;
    const arr = nums.concat(nums);
    let curr = 0, left = 0, minLen = Infinity;
    for (let right = 0; right < arr.length; right++) {
        curr += arr[right];
        while (curr > rem && left <= right) {
            curr -= arr[left++];
        }
        if (curr === rem) {
            if (right - left + 1 < minLen) minLen = right - left + 1;
        }
    }
    if (minLen === Infinity) return -1;
    return full * n + minLen;
};
